, target AS (SELECT s.* FROM sessions s,input WHERE s.id=(args->>'session_id')::uuid)
SELECT jsonb_build_object(
 'session', (SELECT jsonb_build_object('id',id,'status',status,'computer_id',computer_id,'parent_session_id',parent_session_id,'created_at',created_at) FROM target),
 'processes', COALESCE((SELECT jsonb_agg(jsonb_build_object('epoch',p.epoch,'status',p.status,'computer_lease_epoch',p.computer_lease_epoch,'fenced_at',p.fenced_at) ORDER BY p.epoch) FROM session_processes p JOIN target s ON s.environment_id=p.environment_id AND s.id=p.session_id),'[]'::jsonb),
 'turns', COALESCE((SELECT jsonb_agg(jsonb_build_object('id',t.id,'seq',t.seq,'status',t.status,'process_epoch',t.process_epoch,'created_at',t.created_at,'started_at',t.started_at,'terminal_at',t.terminal_at,'result_recorded_at',t.result_recorded_at,'queue_ms',extract(epoch FROM(t.started_at-t.created_at))*1000) ORDER BY t.seq) FROM turns t JOIN target s ON s.environment_id=t.environment_id AND s.id=t.session_id),'[]'::jsonb),
 'leases', COALESCE((SELECT jsonb_agg(jsonb_build_object('epoch',l.epoch,'worker_host_id',l.worker_host_id,'status',l.status,'delivered_at',l.delivered_at,'initialized_at',l.initialized_at,'fenced_at',l.fenced_at) ORDER BY l.epoch) FROM computer_leases l JOIN target s ON (l.environment_id,l.computer_id)=(s.environment_id,s.computer_id)),'[]'::jsonb),
 'saves', COALESCE((SELECT jsonb_agg(jsonb_build_object('id',v.id,'turn_id',v.turn_id,'seq',v.seq,'lease_epoch',v.computer_lease_epoch,'status',v.status,'coverage_max_seq',v.coverage_max_seq,'covered_by_save_id',v.covered_by_save_id,'requested_at',v.requested_at,'flush_acknowledged_at',v.flush_acknowledged_at,'captured_at',v.captured_at,'published_at',v.published_at) ORDER BY v.seq) FROM computer_saves v JOIN target s ON (v.environment_id,v.computer_id)=(s.environment_id,s.computer_id)),'[]'::jsonb),
 'delivery', COALESCE((SELECT jsonb_agg(jsonb_build_object('turn_id',p.turn_id,'role',p.role,'created_at',p.created_at,'posted_at',p.posted_at,'confirmed_at',p.confirmed_at,'desired_revision',p.desired_revision,'confirmed_revision',p.confirmed_revision) ORDER BY p.seq) FROM slack_posts p JOIN target s ON (p.environment_id,p.session_id)=(s.environment_id,s.id)),'[]'::jsonb),
 'save_backlog', (SELECT jsonb_build_object(
   'lease_epoch',l.epoch,
   'oldest_uncovered_seq',(SELECT min(v.seq) FROM computer_saves v WHERE v.environment_id=l.environment_id AND v.computer_id=l.computer_id AND v.computer_lease_epoch=l.epoch AND v.turn_id IS NOT NULL AND v.status IN ('requested','captured')),
   'oldest_uncovered_requested_at',(SELECT min(v.requested_at) FROM computer_saves v WHERE v.environment_id=l.environment_id AND v.computer_id=l.computer_id AND v.computer_lease_epoch=l.epoch AND v.turn_id IS NOT NULL AND v.status IN ('requested','captured')),
   'failed_turn_save_count',(SELECT count(*) FROM computer_saves v WHERE v.environment_id=l.environment_id AND v.computer_id=l.computer_id AND v.turn_id IS NOT NULL AND v.status='failed'),
   'oldest_failed_turn_save_seq',(SELECT min(v.seq) FROM computer_saves v WHERE v.environment_id=l.environment_id AND v.computer_id=l.computer_id AND v.turn_id IS NOT NULL AND v.status='failed'))
   FROM computer_leases l JOIN target s ON (l.environment_id,l.computer_id)=(s.environment_id,s.computer_id) ORDER BY l.epoch DESC LIMIT 1),
 'checkpoints', COALESCE((SELECT jsonb_agg(jsonb_build_object('id',c.id,'status',c.status,'process_epoch',m.process_epoch,'source_lease_epoch',c.source_lease_epoch,'target_lease_epoch',c.target_lease_epoch,'ready_at',c.ready_at,'controls_reconciled_at',c.controls_reconciled_at) ORDER BY c.created_at,c.id) FROM checkpoint_processes m JOIN target s ON s.environment_id=m.environment_id AND s.id=m.session_id JOIN checkpoints c ON c.environment_id=m.environment_id AND c.id=m.checkpoint_id AND c.computer_id=s.computer_id),'[]'::jsonb));
